    return XmlScannerConstants.ALL;
}

@Override
public void visitElement(XmlContext context, Element element) {
    if (!isVectorDrawable(context)) {
        return;
    }
    int minSdk = context.getProject().getMinSdk();
    String tag = element.getTagName();
    if (TAG_CLIP_PATH.equals(tag) && minSdk < 21) {
        context.report(ISSUE, element, context.getLocation(element),
                "The `<clip-path>` element is not fully supported when vector drawables are " +
                "rasterized for older devices; verify the generated output.");
    }
    NamedNodeMap attributes = element.getAttributes();
    for (int i = 0; i < attributes.getLength(); i++) {
        Node node = attributes.item(i);
        if (node.getNodeType() != Node.ATTRIBUTE_NODE) continue;
        Attr attr = (Attr) node;
        if (!ANDROID_URI.equals(attr.getNamespaceURI())) continue;
        String name = attr.getLocalName();
        if (ATTR_FILL_TYPE.equals(name)) {
            if (minSdk < 24) reportAttribute(context, attr);
        } else if (UNSUPPORTED_ATTRIBUTES.contains(name) && minSdk < 21) {
            reportAttribute(context, attr);
        }
    }
}
```
