    private static final String ATTR_STROKE_LINE_JOIN = "strokeLineJoin";
    private static final String ATTR_STROKE_MITER_LIMIT = "strokeMiterLimit";
    private static final String ATTR_AUTO_MIRRORED = "autoMirrored";
    private static final String ATTR_TINT = "tint";
    private static final String ATTR_TINT_MODE = "tintMode";

    private static final Set<String> UNSUPPORTED_ATTRIBUTES = ImmutableSet.of(
            ATTR_TRIM_PATH_START,
            ATTR_TRIM_PATH_END,
            ATTR_TRIM_PATH_OFFSET,
            ATTR_STROKE_LINE_CAP,
            ATTR_STROKE_LINE_JOIN,
            ATTR_STROKE_MITER_LIMIT,
            ATTR_AUTO_MIRRORED,
            ATTR_TINT,
            ATTR_TINT_MODE
    );

    public static final Issue ISSUE = Issue.create(
            "VectorRaster",
            "Vector image generation",
            "...",
            Category.CORRECTNESS,
            5,
            Severity.WARNING,
            new Implementation(VectorDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    private boolean mIsVectorDrawable;

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.DRAWABLE;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return XmlScannerConstants.ALL;
    }

    @Override
    public void visitDocument(XmlContext context, Document document) {
        Element root = document.getDocumentElement();
        mIsVectorDrawable = root != null && TAG_VECTOR.equals(root.getTagName());
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        if (!mIsVectorDrawable) {
            return;
        }

        int minSdk = context.getProject().getMinSdk();
        String tag = element.getTagName();

        if (TAG_VECTOR.equals(tag)) {
            checkSize(context, element, minSdk);
        } else if (TAG_CLIP_PATH.equals(tag)) {
            if (minSdk < 21) {
                context.report(ISSUE, element, context.getLocation(element),
                        "The `<clip-path>` element is not fully supported when vector drawables are rasterized for older devices; verify the generated output.");
            }
        } else if (TAG_GRADIENT.equals(tag)) {
            if (minSdk < 24) {
                context.report(ISSUE, element, context.getLocation(element),
                        "Vector drawables with gradients are not supported when rasterized for older devices; verify the generated output.");
            }
        }

        NamedNodeMap attributes = element.getAttributes();
        for (int i = 0; i < attributes.getLength(); i++) {
            Node node = attributes.item(i);
            if (!(node instanceof Attr)) {
                continue;
            }
            Attr attr = (Attr) node;
            if (!ANDROID_URI.equals(attr.getNamespaceURI())) {
                continue;
            }
            String name = attr.getLocalName();
            if (ATTR_FILL_TYPE.equals(name)) {
                if (minSdk < 24) {
                    reportAttribute(context, attr);
                }
            } else if (UNSUPPORTED_ATTRIBUTES.contains(name) && minSdk < 21) {
                reportAttribute(context, attr);
            }
        }
    }

    private static void checkSize(XmlContext context, Element element, int minSdk) {
        if (minSdk >= 21) {
            return;
        }
        String width = element.getAttributeNS(ANDROID_URI, ATTR_WIDTH);
        String height = element.getAttributeNS(ANDROID_URI, ATTR_HEIGHT);
        if (isLargeDimension(width) || isLargeDimension(height)) {
            context.report(ISSUE, element, context.getLocation(element),
                    "Very large vector (width/height > 200dp): when rasterized, this will produce large bitmaps. Consider using a smaller vector or a bitmap.");
        }
    }

    private static boolean isLargeDimension(String value) {
        if (value == null || !value.endsWith("dp")) {
            return false;
        }
        try {
            int v = Integer.parseInt(value.substring(0, value.length() - 2));
            return v > 200;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    private static void reportAttribute(XmlContext context, Attr attr) {
        String name = attr.getLocalName();
        context.report(ISSUE, attr, context.getLocation(attr),
                "Attribute `android:" + name + "` is not fully supported when vector drawables are rasterized for older devices; verify the generated output.");
    }
}
